{
    lv_event_code_t code = lv_event_get_code(e);

    if (code == LV_EVENT_CLICKED)
    {
        knowledge_card_t *card = card_manager_get_next_card();
        if (card != NULL)
        {
            ui_update_card_display(g_app_ctx);
        }
    }
}

