#define GENERATION_TIMEOUT  30    /* 生成超时30秒 */

/****************************************************************************
 * Private Data
 ****************************************************************************/

static app_context_t g_app_context;
static uv_loop_t g_uv_loop;
static bool g_running = true;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: wifi_monitor_cb
 *
 * Description:
 *   WiFi 状态监控回调
 *
 ****************************************************************************/

static void wifi_monitor_cb(uv_timer_t *handle)
{
    app_context_t *ctx = (app_context_t *)handle->data;
    int ret;

    ret = wifi_check_connection();
    if (ret == 0 && !ctx->wifi_connected)
    {
        ctx->wifi_connected = true;
        ui_show_status(ctx, "WiFi 已连接");
        printf("WiFi connected\n");
    }
    else if (ret != 0 && ctx->wifi_connected)
    {
        ctx->wifi_connected = false;
        ui_show_status(ctx, "WiFi 未连接");
        printf("WiFi disconnected\n");
    }
}

/****************************************************************************
 * Name: generate_knowledge_thread
 *
 * Description:
 *   知识生成线程
 *
 ****************************************************************************/

static void *generate_knowledge_thread(void *arg)
{
    app_context_t *ctx = (app_context_t *)arg;
    int ret;

    /* 生成大纲 */

    ret = llm_generate_outline(ctx->current_topic.topic, &ctx->current_topic);
    if (ret < 0)
    {
        fprintf(stderr, "ERROR: Failed to generate outline: %d\n", ret);
        ui_set_state(ctx, UI_STATE_ERROR);
        return NULL;
    }

    /* 为每个卡片生成内容 */

    for (int i = 0; i < ctx->current_topic.card_count && g_running; i++)
    {
        if (!ctx->current_topic.cards[i].is_loaded)
        {
            ret = llm_generate_card_content(&ctx->current_topic.cards[i]);
            if (ret < 0)
            {
                fprintf(stderr, "WARNING: Failed to generate content for card %d: %d\n",
                        i, ret);
                /* 继续处理其他卡片 */
            }
        }
    }

    /* 保存主题 */

    card_manager_save_topic(ctx->current_topic.topic);

    /* 更新 UI */

    ui_set_state(ctx, UI_STATE_DISPLAYING);
    ui_update_card_display(ctx);

    printf("Knowledge generation completed\n");
    return NULL;
}

/****************************************************************************
 * Name: start_knowledge_generation
 *
 * Description:
 *   开始知识生成
 *
 ****************************************************************************/

static int start_knowledge_generation(app_context_t *ctx, const char *topic)
{
    pthread_t thread;
    pthread_attr_t attr;
    int ret;

    if (ctx == NULL || topic == NULL)
    {
        return -EINVAL;
    }

    /* 检查 WiFi 连接 */

    if (!ctx->wifi_connected)
    {
        ui_show_status(ctx, "请先连接 WiFi");
        return -ENOTCONN;
    }

    /* 加载或创建主题 */

    ret = card_manager_load_topic(topic);
    if (ret < 0)
    {
        fprintf(stderr, "ERROR: Failed to load topic: %d\n", ret);
        return ret;
    }

    /* 检查是否已生成 */

    if (ctx->current_topic.outline_generated &&
        ctx->current_topic.card_count > 0)
    {
        /* 已有数据，直接显示 */

        ui_set_state(ctx, UI_STATE_DISPLAYING);
        ui_update_card_display(ctx);
        return 0;
    }

    /* 开始生成 */

    ui_set_state(ctx, UI_STATE_GENERATING);

    /* 创建生成线程 */

    pthread_attr_init(&attr);
    pthread_attr_setstacksize(&attr, 8192);

    ret = pthread_create(&thread, &attr, generate_knowledge_thread, ctx);
    pthread_attr_destroy(&attr);

    if (ret != 0)
    {
        fprintf(stderr, "ERROR: Failed to create thread: %d\n", ret);
        ui_set_state(ctx, UI_STATE_ERROR);
        return -ret;
    }

    /* 分离线程 */

    pthread_detach(thread);

    return 0;
}

/****************************************************************************
 * Name: voice_input_callback
 *
 * Description:
 *   语音输入回调函数
 *
 ****************************************************************************/

static void voice_input_callback(const char *text)
{
    app_context_t *ctx = &g_app_context;

    if (text == NULL || strlen(text) == 0)
    {
        return;
    }

    printf("Voice input: %s\n", text);

    /* 停止监听 */

    voice_stop_listening();

    /* 开始生成知识 */

    start_knowledge_generation(ctx, text);
}

/****************************************************************************
 * Name: lv_nuttx_uv_loop
 *
 * Description:
 *   LVGL 与 libuv 事件循环集成
 *
 ****************************************************************************/

static void lv_nuttx_uv_loop(uv_loop_t *loop, lv_nuttx_result_t *result)
{
    lv_nuttx_uv_t uv_info;
    void *data;

    memset(&uv_info, 0, sizeof(uv_info));
    uv_info.loop = loop;
    uv_info.disp = result->disp;
    uv_info.indev = result->indev;

    data = lv_nuttx_uv_init(&uv_info);
    if (data == NULL)
    {
        fprintf(stderr, "ERROR: Failed to initialize LVGL UV loop\n");
        return;
    }

    /* 主事件循环 */

    uv_run(loop, UV_RUN_DEFAULT);

    lv_nuttx_uv_deinit(data);
}

