/****************************************************************************
 * Name: knowledge_cards_main
 *
 * Description:
 *   主入口函数
 *
 ****************************************************************************/

int main(int argc, char *argv[])
{
    lv_nuttx_result_t result;
    int ret;

    printf("Starting %s application\n", APP_NAME);

    /* 初始化应用上下文 */

    memset(&g_app_context, 0, sizeof(g_app_context));
    g_app_context.state = UI_STATE_IDLE;
    g_app_context.wifi_connected = false;

    /* 初始化 libuv 事件循环 */

    ret = uv_loop_init(&g_uv_loop);
    if (ret != 0)
    {
        fprintf(stderr, "ERROR: Failed to init UV loop: %d\n", ret);
        return -1;
    }

    /* 初始化 LVGL */

    lv_init();

    /* 初始化 NuttX 显示驱动 */

    ret = lv_nuttx_init(NULL, &result);
    if (ret != 0)
    {
        fprintf(stderr, "ERROR: Failed to init NuttX display: %d\n", ret);
        return -1;
    }

    /* 初始化字体 */

    g_app_context.fonts.size_16 = &lv_font_montserrat_16;
    g_app_context.fonts.size_20 = &lv_font_montserrat_20;
    g_app_context.fonts.size_24 = &lv_font_montserrat_24;
    g_app_context.fonts.size_32 = &lv_font_montserrat_32;

    /* 初始化卡片管理器 */

    ret = card_manager_init();
    if (ret < 0)
    {
        fprintf(stderr, "ERROR: Failed to init card manager: %d\n", ret);
        return -1;
    }

    /* 初始化 LLM 客户端 */

    llm_config_t llm_config;
    memset(&llm_config, 0, sizeof(llm_config));

    /* 从环境变量或配置文件读取 API 配置 */

    const char *api_key = getenv("LLM_API_KEY");
    if (api_key != NULL)
    {
        strncpy(llm_config.api_key, api_key, LLM_API_KEY_MAX_LEN - 1);
    }

    const char *endpoint = getenv("LLM_ENDPOINT");
    if (endpoint != NULL)
    {
        strncpy(llm_config.endpoint, endpoint, LLM_ENDPOINT_MAX_LEN - 1);
    }

    const char *model = getenv("LLM_MODEL");
    if (model != NULL)
    {
        strncpy(llm_config.model, model, sizeof(llm_config.model) - 1);
    }

    ret = llm_init(&llm_config);
    if (ret < 0)
    {
        fprintf(stderr, "ERROR: Failed to init LLM client: %d\n", ret);
        return -1;
    }

    /* 初始化语音识别 */

    ret = voice_init();
    if (ret < 0)
    {
        fprintf(stderr, "WARNING: Voice init failed: %d\n", ret);
        /* 不是致命错误，继续运行 */
    }

    /* 初始化 UI */

    ret = ui_init(&g_app_context);
    if (ret < 0)
    {
        fprintf(stderr, "ERROR: Failed to init UI: %d\n", ret);
        return -1;
    }

    /* 设置 WiFi 监控定时器 */

    uv_timer_t wifi_timer;
    uv_timer_init(&g_uv_loop, &wifi_timer);
    wifi_timer.data = &g_app_context;
    uv_timer_start(&wifi_timer, wifi_monitor_cb, 0, WIFI_CHECK_INTERVAL);

    /* 如果命令行提供了主题，直接加载 */

    if (argc > 1)
    {
        start_knowledge_generation(&g_app_context, argv[1]);
    }

    /* 进入主事件循环 */

    printf("Entering main event loop\n");
    lv_nuttx_uv_loop(&g_uv_loop, &result);

    /* 清理资源 */

    g_running = false;
    llm_cleanup();
    uv_loop_close(&g_uv_loop);

    printf("%s application exited\n", APP_NAME);
    return 0;
}

