/****************************************************************************
 * WiFi Functions
 ****************************************************************************/

/****************************************************************************
 * Name: wifi_check_connection
 *
 * Description:
 *   检查 WiFi 连接状态
 *
 ****************************************************************************/

int wifi_check_connection(void)
{
    struct hostent *server;
    int sock;
    struct sockaddr_in server_addr;
    int ret;

    /* 尝试 DNS 解析 */

    server = gethostbyname(WIFI_TEST_HOST);
    if (server == NULL)
    {
        return -ENXIO;
    }

    /* 尝试连接 */

    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0)
    {
        return -errno;
    }

    /* 设置非阻塞 */

    int flags = fcntl(sock, F_GETFL, 0);
    fcntl(sock, F_SETFL, flags | O_NONBLOCK);

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    memcpy(&server_addr.sin_addr.s_addr, server->h_addr, server->h_length);
    server_addr.sin_port = htons(WIFI_TEST_PORT);

    ret = connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr));
    close(sock);

    /* 非阻塞连接会返回 EINPROGRESS */

    if (ret < 0 && errno != EINPROGRESS)
    {
        return -errno;
    }

    return 0;
}

/****************************************************************************
 * Name: wifi_connect
 *
 * Description:
 *   连接 WiFi（需要系统配置）
 *
 ****************************************************************************/

int wifi_connect(void)
{
    /* WiFi 连接需要系统级配置，这里只是检查状态 */

    printf("WiFi connection should be configured at system level\n");
    printf("Use 'ifup wlan0' and 'wapi' commands to configure\n");

    return wifi_check_connection();
}

