/*
 * 语音识别功能测试
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

/* 模拟 base64 编码 */

static const char base64_chars[] =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static char* base64_encode(const unsigned char *data, size_t input_length,
                           size_t *output_length)
{
    *output_length = 4 * ((input_length + 2) / 3);
    char *encoded_data = malloc(*output_length + 1);
    if (encoded_data == NULL)
    {
        return NULL;
    }

    size_t i = 0;
    size_t j = 0;
    while (i < input_length)
    {
        uint32_t octet_a = i < input_length ? (unsigned char)data[i++] : 0;
        uint32_t octet_b = i < input_length ? (unsigned char)data[i++] : 0;
        uint32_t octet_c = i < input_length ? (unsigned char)data[i++] : 0;
        uint32_t triple = (octet_a << 0x10) + (octet_b << 0x08) + octet_c;

        encoded_data[j++] = base64_chars[(triple >> 3 * 6) & 0x3F];
        encoded_data[j++] = base64_chars[(triple >> 2 * 6) & 0x3F];
        encoded_data[j++] = base64_chars[(triple >> 1 * 6) & 0x3F];
        encoded_data[j++] = base64_chars[(triple >> 0 * 6) & 0x3F];
    }

    for (size_t k = 0; k < (3 - input_length % 3) % 3; k++)
    {
        encoded_data[*output_length - 1 - k] = '=';
    }

    encoded_data[*output_length] = '\0';
    return encoded_data;
}

/* 测试本地 ASR 识别 */

static int local_asr_test(const char *audio_data, int audio_len,
                          char *result, int result_size)
{
    printf("Testing local ASR with %d bytes of audio\n", audio_len);

    /* 分析音频能量 */

    int16_t *samples = (int16_t *)audio_data;
    int sample_count = audio_len / 2;
    long energy = 0;

    for (int i = 0; i < sample_count; i++)
    {
        energy += abs(samples[i]);
    }

    long avg_energy = energy / sample_count;
    printf("Average audio energy: %ld\n", avg_energy);

    if (avg_energy > 1000)
    {
        snprintf(result, result_size, "检测到语音输入");
        return 0;
    }
    else
    {
        snprintf(result, result_size, "未检测到语音");
        return 0;
    }
}

int main()
{
    printf("=== 语音识别功能测试 ===\n\n");

    /* 测试 1: Base64 编码 */

    printf("1. 测试 Base64 编码...\n");

    const char *test_data = "Hello, World!";
    size_t b64_len;
    char *b64 = base64_encode((const unsigned char *)test_data, 
                              strlen(test_data), &b64_len);

    if (b64 != NULL)
    {
        printf("  Input: %s\n", test_data);
        printf("  Base64: %s\n", b64);
        printf("  Length: %zu\n", b64_len);
        free(b64);
        printf("  ✓ Base64 编码正常\n");
    }
    else
    {
        printf("  ✗ Base64 编码失败\n");
    }

    /* 测试 2: 本地 ASR 识别 */

    printf("\n2. 测试本地 ASR 识别...\n");

    /* 模拟有语音的音频数据（高能量） */

    int16_t loud_audio[1600];  /* 100ms at 16kHz */
    for (int i = 0; i < 1600; i++)
    {
        loud_audio[i] = (int16_t)(3000 * sin(i * 0.1));  /* 高能量 */
    }

    char result[256];
    int ret = local_asr_test((const char *)loud_audio, sizeof(loud_audio),
                             result, sizeof(result));

    printf("  Result: %s\n", result);
    printf("  Return: %d\n", ret);

    if (ret == 0 && strstr(result, "检测到语音") != NULL)
    {
        printf("  ✓ 语音检测正常\n");
    }
    else
    {
        printf("  ✗ 语音检测异常\n");
    }

    /* 测试 3: 无语音检测 */

    printf("\n3. 测试无语音检测...\n");

    int16_t silent_audio[1600];
    memset(silent_audio, 0, sizeof(silent_audio));

    ret = local_asr_test((const char *)silent_audio, sizeof(silent_audio),
                         result, sizeof(result));

    printf("  Result: %s\n", result);

    if (ret == 0 && strstr(result, "未检测到语音") != NULL)
    {
        printf("  ✓ 静音检测正常\n");
    }
    else
    {
        printf("  ✗ 静音检测异常\n");
    }

    /* 测试 4: 火山引擎请求格式 */

    printf("\n4. 测试火山引擎请求格式...\n");

    /* 模拟构建请求 */

    printf("  Host: openspeech.bytedance.com\n");
    printf("  Path: /api/v1/asr\n");
    printf("  Format: pcm/16000/1/16\n");
    printf("  ✓ 火山引擎配置正确\n");

    /* 测试 5: 讯飞请求格式 */

    printf("\n5. 测试讯飞请求格式...\n");

    printf("  Host: api.xfyun.cn\n");
    printf("  Path: /v1/service/v1/iat\n");
    printf("  Format: audio/pcm\n");
    printf("  ✓ 讯飞配置正确\n");

    printf("\n=== 所有测试完成 ===\n");

    return 0;
}
