/****************************************************************************
 * packages/demos/knowledge_cards/tests/test_main.c
 *
 * 单元测试主入口
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

/****************************************************************************
 * Test Function Prototypes
 ****************************************************************************/

/* LLM 客户端测试 */

extern int test_llm_init(void);
extern int test_llm_parse_response(void);
extern int test_llm_url_parsing(void);

/* 卡片管理器测试 */

extern int test_card_manager_init(void);
extern int test_card_manager_load_save(void);
extern int test_card_manager_navigation(void);

/* 语音识别测试 */

extern int test_voice_init(void);
extern int test_base64_encode(void);
extern int test_local_asr(void);
extern int test_voice_state_machine(void);

/* WiFi 工具测试 */

extern int test_wifi_check_connection(void);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int g_tests_passed = 0;
static int g_tests_failed = 0;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void run_test(const char *name, int (*test_func)(void))
{
    printf("\n[TEST] %s\n", name);
    printf("────────────────────────────────────────\n");

    int ret = test_func();

    if (ret == 0)
    {
        printf("✓ PASSED\n");
        g_tests_passed++;
    }
    else
    {
        printf("✗ FAILED (ret=%d)\n", ret);
        g_tests_failed++;
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
    printf("╔════════════════════════════════════════╗\n");
    printf("║    Knowledge Cards 单元测试           ║\n");
    printf("╚════════════════════════════════════════╝\n");

    /* LLM 客户端测试 */

    printf("\n╔════════════════════════════════════════╗\n");
    printf("║         LLM 客户端测试                 ║\n");
    printf("╚════════════════════════════════════════╝\n");

    run_test("LLM 初始化", test_llm_init);
    run_test("LLM 响应解析", test_llm_parse_response);
    run_test("URL 解析", test_llm_url_parsing);

    /* 卡片管理器测试 */

    printf("\n╔════════════════════════════════════════╗\n");
    printf("║         卡片管理器测试                 ║\n");
    printf("╚════════════════════════════════════════╝\n");

    run_test("卡片管理器初始化", test_card_manager_init);
    run_test("卡片加载保存", test_card_manager_load_save);
    run_test("卡片导航", test_card_manager_navigation);

    /* 语音识别测试 */

    printf("\n╔════════════════════════════════════════╗\n");
    printf("║         语音识别测试                   ║\n");
    printf("╚════════════════════════════════════════╝\n");

    run_test("语音初始化", test_voice_init);
    run_test("Base64 编码", test_base64_encode);
    run_test("本地 ASR", test_local_asr);
    run_test("语音状态机", test_voice_state_machine);

    /* WiFi 工具测试 */

    printf("\n╔════════════════════════════════════════╗\n");
    printf("║         WiFi 工具测试                  ║\n");
    printf("╚════════════════════════════════════════╝\n");

    run_test("WiFi 连接检测", test_wifi_check_connection);

    /* 测试总结 */

    printf("\n╔════════════════════════════════════════╗\n");
    printf("║         测试总结                       ║\n");
    printf("╚════════════════════════════════════════╝\n");
    printf("\n总测试数: %d\n", g_tests_passed + g_tests_failed);
    printf("通过: %d\n", g_tests_passed);
    printf("失败: %d\n", g_tests_failed);

    if (g_tests_failed == 0)
    {
        printf("\n✓ 所有测试通过！\n\n");
        return 0;
    }
    else
    {
        printf("\n✗ 有 %d 个测试失败\n\n", g_tests_failed);
        return 1;
    }
}

/****************************************************************************
 * packages/demos/knowledge_cards/tests/test_llm_client.c
 *
 * LLM 客户端单元测试
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <cJSON.h>

/* 包含被测试的头文件 */

#include "../include/knowledge_cards.h"

/****************************************************************************
 * Private Functions - 辅助函数
 ****************************************************************************/

static int test_assert(int condition, const char *message)
{
    if (!condition)
    {
        fprintf(stderr, "  ASSERT FAILED: %s\n", message);
        return -1;
    }
    printf("  ✓ %s\n", message);
    return 0;
}

/****************************************************************************
 * Public Functions - 测试用例
 ****************************************************************************/

/****************************************************************************
 * Name: test_llm_init
 *
 * Description:
 *   测试 LLM 客户端初始化
 *
 ****************************************************************************/

int test_llm_init(void)
{
    llm_config_t config;
    int ret;

    /* 测试 1: 正常初始化 */

    printf("\n测试 1: 正常初始化\n");

    memset(&config, 0, sizeof(config));
    strncpy(config.api_key, "test-api-key", sizeof(config.api_key) - 1);
    strncpy(config.endpoint, "https://api.openai.com/v1/chat/completions",
            sizeof(config.endpoint) - 1);
    strncpy(config.model, "gpt-3.5-turbo", sizeof(config.model) - 1);
    config.max_tokens = 512;
    config.timeout = 30;

    ret = llm_init(&config);
    if (test_assert(ret == 0, "LLM 初始化应该成功") != 0)
    {
        return -1;
    }

    /* 测试 2: 空配置 */

    printf("\n测试 2: 空配置\n");

    ret = llm_init(NULL);
    if (test_assert(ret != 0, "空配置应该失败") != 0)
    {
        return -1;
    }

    /* 测试 3: 默认值设置 */

    printf("\n测试 3: 默认值设置\n");

    memset(&config, 0, sizeof(config));
    strncpy(config.api_key, "test-key", sizeof(config.api_key) - 1);
    /* 不设置 endpoint、model、max_tokens、timeout */

    ret = llm_init(&config);
    if (test_assert(ret == 0, "默认值初始化应该成功") != 0)
    {
        return -1;
    }

    /* 验证默认值 */

    if (test_assert(strlen(config.endpoint) > 0, "endpoint 应该有默认值") != 0)
    {
        return -1;
    }

    if (test_assert(strlen(config.model) > 0, "model 应该有默认值") != 0)
    {
        return -1;
    }

    if (test_assert(config.max_tokens > 0, "max_tokens 应该有默认值") != 0)
    {
        return -1;
    }

    if (test_assert(config.timeout > 0, "timeout 应该有默认值") != 0)
    {
        return -1;
    }

    return 0;
}

/****************************************************************************
 * Name: test_llm_parse_response
 *
 * Description:
 *   测试 LLM 响应解析
 *
 ****************************************************************************/

int test_llm_parse_response(void)
{
    /* 测试 1: 解析有效的 OpenAI 响应 */

    printf("\n测试 1: 解析有效的 OpenAI 响应\n");

    const char *valid_response =
        "HTTP/1.1 200 OK\r\n"
        "Content-Type: application/json\r\n"
        "\r\n"
        "{"
        "\"choices\": ["
        "  {"
        "    \"message\": {"
        "      \"content\": \"测试内容\""
        "    }"
        "  }"
        "]"
        "}";

    char content[256];
    int ret = parse_json_response(valid_response, content, sizeof(content));

    if (test_assert(ret == 0, "解析应该成功") != 0)
    {
        return -1;
    }

    if (test_assert(strcmp(content, "测试内容") == 0, "内容应该匹配") != 0)
    {
        return -1;
