int test_local_asr(void)
{
    char result[256];
    int ret;

    /* 测试 1: 高能量音频（有语音） */

    printf("\n测试 1: 高能量音频（有语音）\n");

    int16_t loud_audio[1600];  /* 100ms at 16kHz */
    for (int i = 0; i < 1600; i++)
